mapper.select:
SELECT temp.supplier_id, temp.supplier_name, temp.branch_company_id, temp.branch_company_name, temp.supplier_bank_name, temp.supplier_bank_account, temp.bool_personal_enum, SUM( temp.freight ) AS freight FROM ( SELECT IFNULL(sp.supplier_id, 0) AS supplier_id, (CASE sp.bool_personal_enum when 0 then ss.`name` else '个人' END) AS supplier_name, ss.bank_name as supplier_bank_name, ss.bank_account as supplier_bank_account, p.contract_sign_body_id AS branch_company_id, bc.`name` AS branch_company_name, c.total_price AS freight, sp.bool_personal_enum FROM mes_building_cargo_list AS c INNER JOIN mes_building_supplier_price AS sp ON sp.id = c.supplier_price_id AND sp.bool_delete_enum = 0 LEFT JOIN contract_project AS p ON p.id = c.project_id AND p.bool_delete_enum = 0 LEFT JOIN scm_supplier AS ss ON sp.supplier_id = ss.id AND ss.bool_delete_enum = 0 INNER JOIN sys_branch_company AS bc ON p.contract_sign_body_id = bc.id AND bc.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 AND c.status IN (4, 8)
AND DATE_FORMAT(c.create_time,'%Y') = #{year}
AND ss.name LIKE concat('%',#{supplierName},'%')
UNION ALL SELECT slo.supplier_id, ss.`name` AS supplier_name, ss.bank_name as supplier_bank_name, ss.bank_account as supplier_bank_account, spo.branch_company_id, bc.`name` AS branch_company_name, slo.freight, 0 bool_personal_enum FROM scm_logistics_order AS slo INNER JOIN scm_purchase_order AS spo ON slo.purchase_id = spo.id AND spo.bool_delete_enum = 0 LEFT JOIN sys_branch_company AS bc ON spo.branch_company_id = bc.id AND bc.bool_delete_enum = 0 LEFT JOIN scm_supplier AS ss ON slo.supplier_id = ss.id AND ss.bool_delete_enum = 0 WHERE slo.inbound_review_status = 2
AND DATE_FORMAT(slo.create_time,'%Y') = #{year}
AND ss.name LIKE concat('%',#{supplierName},'%')
) AS temp
GROUP BY temp.supplier_id, temp.supplier_name, temp.branch_company_id, temp.branch_company_name, temp.supplier_bank_name, temp.supplier_bank_account,temp.bool_personal_enum

SELECT slo.purchase_id, slo.purchase_sn AS serial_number, slo.supplier_id, ss.`name` AS supplier_name, sum(slo.freight) AS freight FROM scm_logistics_order AS slo INNER JOIN scm_purchase_order AS spo ON slo.purchase_id = spo.id AND spo.bool_delete_enum = 0 LEFT JOIN scm_supplier AS ss ON slo.supplier_id = ss.id AND ss.bool_delete_enum = 0 WHERE slo.bool_delete_enum = 0 AND slo.inbound_review_status = 2
AND slo. purchase_id = #{purchaseId}
AND slo.supplier_id = #{supplierId}
AND slo.supplier_id IS NULL
AND spo.branch_company_id = #{branchCompanyId}
GROUP BY slo.purchase_id, slo.purchase_sn, slo.supplier_id, ss.`name`

SELECT
IFNULL(SUM(slo.freight), 0)
FROM scm_logistics_order AS slo
INNER JOIN scm_purchase_order AS spo ON slo.purchase_id = spo.id AND spo.bool_delete_enum = 0
WHERE slo.bool_delete_enum = 0
AND slo.inbound_review_status = 2

    AND slo.purchase_id = #{purchaseId}


    AND spo.branch_company_id = #{branchCompanyId}


    AND slo.supplier_id = #{supplierId}


    AND slo.create_time >= #{startDate}


    AND slo.create_time <= #{endDate}

SELECT temp.* FROM (SELECT temp.supplier_id, temp.supplier_name, IFNULL(SUM(temp.freight),0) AS amount, SUM(temp.payment_amount) as payment_amount, SUM(temp.invoice_amount) as invoice_amount FROM( SELECT ss.id AS supplier_id, ss.`name` AS supplier_name, (CASE sp.price_type WHEN 1 THEN c.actual_weight * sp.price / 1000 ELSE sp.price END ) AS freight, (select IFNULL(SUM(actually_payment_amount),0) from contract_supplier_payment_detail where receiving_unit_id = sp.supplier_id AND bool_delete_enum = 0 and audit_status = 2 AND type = 2) as payment_amount, (select IFNULL(SUM(invoice_amount),0) from contract_supplier_invoice where bool_delete_enum = 0 and audit_status = 2 and supplier_id = sp.supplier_id) as invoice_amount FROM mes_building_cargo_list AS c INNER JOIN mes_building_supplier_price AS sp ON sp.id = c.supplier_price_id AND sp.bool_delete_enum = 0 LEFT JOIN scm_supplier AS ss ON sp.supplier_id = ss.id AND ss.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0
and c.create_time >= #{startDate}
and c.create_time <= #{endDate}
UNION ALL
SELECT slo.supplier_id, ss.`name` AS supplier_name, slo.freight, (SELECT IFNULL(SUM(actually_payment_amount),0) FROM contract_supplier_payment_detail WHERE bool_delete_enum = 0 AND audit_status = 2 AND type = 1 AND receiving_unit_id = slo.supplier_id ) AS payment_amount, (select IFNULL(SUM(invoice_amount),0) from contract_supplier_invoice where bool_delete_enum = 0 and audit_status = 2 and supplier_id = slo.supplier_id) as invoice_amount FROM scm_logistics_order AS slo INNER JOIN scm_purchase_order AS spo ON slo.purchase_id = spo.id AND spo.bool_delete_enum = 0 LEFT JOIN scm_supplier AS ss ON slo.supplier_id = ss.id AND ss.bool_delete_enum = 0 WHERE slo.bool_delete_enum = 0 AND slo.inbound_review_status = 2
and slo.create_time >= #{startDate}
and slo.create_time <= #{endDate}
) AS temp GROUP BY temp.supplier_id, temp.supplier_name) AS temp
and temp.supplier_name like concat('%',#{supplierName},'%')
and temp.payment_amount < temp.amount
and temp.payment_amount >= temp.amount
AND temp.invoice_amount < temp.amount
AND temp.invoice_amount >= temp.amount
